/* Quantum Rose Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="quantum-rose-light"] {
  --background: rgb(255, 240, 248);
  --foreground: rgb(146, 18, 91);
  --card: rgb(253, 246, 251);
  --card-foreground: rgb(146, 18, 91);
  --popover: rgb(253, 246, 251);
  --popover-foreground: rgb(146, 18, 91);
  --primary: rgb(229, 10, 122);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(254, 213, 254);
  --secondary-foreground: rgb(146, 18, 91);
  --muted: rgb(255, 226, 241);
  --muted-foreground: rgb(190, 66, 130);
  --accent: rgb(255, 195, 228);
  --accent-foreground: rgb(146, 18, 91);
  --destructive: rgb(207, 56, 104);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(253, 201, 230);
  --input: rgb(254, 213, 254);
  --ring: rgb(229, 10, 122);
  --chart-1: rgb(229, 10, 122);
  --chart-2: rgb(195, 78, 151);
  --chart-3: rgb(152, 106, 180);
  --chart-4: rgb(114, 111, 191);
  --chart-5: rgb(95, 133, 255);
  --radius: 0.5rem;
  --sidebar: rgb(253, 237, 245);
  --sidebar-foreground: rgb(146, 18, 91);
  --sidebar-primary: rgb(229, 10, 122);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(255, 195, 228);
  --sidebar-accent-foreground: rgb(146, 18, 91);
  --sidebar-border: rgb(252, 222, 239);
  --sidebar-ring: rgb(229, 10, 122);
  --font-sans: Poppins, sans-serif;
  --font-serif: Playfair Display, serif;
  --font-mono: Space Mono, monospace;
  --shadow-color: rgba(130, 23, 77, 0.12);
  --shadow-opacity: 0.18;
  --shadow-blur: 0px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 3px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 3px 0px 0px hsl(330 70% 30% / 0.09);
  --shadow-xs: 0px 3px 0px 0px hsl(330 70% 30% / 0.09);
  --shadow-sm:
    0px 3px 0px 0px hsl(330 70% 30% / 0.18),
    0px 1px 2px -1px hsl(330 70% 30% / 0.18);
  --shadow:
    0px 3px 0px 0px hsl(330 70% 30% / 0.18),
    0px 1px 2px -1px hsl(330 70% 30% / 0.18);
  --shadow-md:
    0px 3px 0px 0px hsl(330 70% 30% / 0.18),
    0px 2px 4px -1px hsl(330 70% 30% / 0.18);
  --shadow-lg:
    0px 3px 0px 0px hsl(330 70% 30% / 0.18),
    0px 4px 6px -1px hsl(330 70% 30% / 0.18);
  --shadow-xl:
    0px 3px 0px 0px hsl(330 70% 30% / 0.18),
    0px 8px 10px -1px hsl(330 70% 30% / 0.18);
  --shadow-2xl: 0px 3px 0px 0px hsl(330 70% 30% / 0.45);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="quantum-rose-dark"] {
  --background: rgb(25, 10, 33);
  --foreground: rgb(254, 178, 254);
  --card: rgb(43, 19, 54);
  --card-foreground: rgb(254, 178, 254);
  --popover: rgb(43, 19, 54);
  --popover-foreground: rgb(254, 178, 254);
  --primary: rgb(253, 106, 237);
  --primary-foreground: rgb(24, 5, 24);
  --secondary: rgb(70, 33, 79);
  --secondary-foreground: rgb(254, 178, 254);
  --muted: rgb(51, 24, 66);
  --muted-foreground: rgb(213, 122, 213);
  --accent: rgb(91, 32, 94);
  --accent-foreground: rgb(254, 178, 254);
  --destructive: rgb(252, 43, 117);
  --destructive-foreground: rgb(248, 248, 248);
  --border: rgb(75, 28, 96);
  --input: rgb(70, 33, 79);
  --ring: rgb(253, 106, 237);
  --chart-1: rgb(253, 106, 237);
  --chart-2: rgb(196, 87, 228);
  --chart-3: rgb(143, 96, 252);
  --chart-4: rgb(112, 117, 224);
  --chart-5: rgb(83, 121, 253);
  --radius: 0.5rem;
  --sidebar: rgb(27, 12, 36);
  --sidebar-foreground: rgb(254, 178, 254);
  --sidebar-primary: rgb(253, 106, 237);
  --sidebar-primary-foreground: rgb(24, 5, 24);
  --sidebar-accent: rgb(91, 32, 94);
  --sidebar-accent-foreground: rgb(254, 178, 254);
  --sidebar-border: rgb(75, 28, 96);
  --sidebar-ring: rgb(253, 106, 237);
  --font-sans: Quicksand, sans-serif;
  --font-serif: Playfair Display, serif;
  --font-mono: Space Mono, monospace;
  --shadow-color: rgba(229, 26, 230, 0.25);
  --shadow-opacity: 0.18;
  --shadow-blur: 0px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 3px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 3px 0px 0px hsl(300 80% 50% / 0.09);
  --shadow-xs: 0px 3px 0px 0px hsl(300 80% 50% / 0.09);
  --shadow-sm:
    0px 3px 0px 0px hsl(300 80% 50% / 0.18),
    0px 1px 2px -1px hsl(300 80% 50% / 0.18);
  --shadow:
    0px 3px 0px 0px hsl(300 80% 50% / 0.18),
    0px 1px 2px -1px hsl(300 80% 50% / 0.18);
  --shadow-md:
    0px 3px 0px 0px hsl(300 80% 50% / 0.18),
    0px 2px 4px -1px hsl(300 80% 50% / 0.18);
  --shadow-lg:
    0px 3px 0px 0px hsl(300 80% 50% / 0.18),
    0px 4px 6px -1px hsl(300 80% 50% / 0.18);
  --shadow-xl:
    0px 3px 0px 0px hsl(300 80% 50% / 0.18),
    0px 8px 10px -1px hsl(300 80% 50% / 0.18);
  --shadow-2xl: 0px 3px 0px 0px hsl(300 80% 50% / 0.45);
}
